// Normalizador Omnicanal de Entradas para Cazador de Ofertas
const item = $input.first().json;

let canal = 'whatsapp';
let remitente = '';
let mensaje = '';
let lat = null;
let lon = null;

// 1. Detección de origen WhatsApp (Meta Cloud API, Baileys o Whapify)
if (item.entry && item.entry[0]?.changes && item.entry[0].changes[0]?.value?.messages) {
  canal = 'whatsapp';
  const msgObj = item.entry[0].changes[0].value.messages[0];
  remitente = msgObj.from || '';
  if (msgObj.type === 'location') {
    lat = msgObj.location.latitude;
    lon = msgObj.location.longitude;
    mensaje = 'mi ubicacion actual';
  } else if (msgObj.text) {
    mensaje = msgObj.text.body || '';
  }
} else if (item.message && item.message.chat) {
  // 2. Detección de origen Telegram (Bot API)
  canal = 'telegram';
  remitente = item.message.from?.phone_number || item.message.chat?.id?.toString() || '';
  if (item.message.location) {
    lat = item.message.location.latitude;
    lon = item.message.location.longitude;
    mensaje = 'mi ubicacion gps';
  } else {
    mensaje = item.message.text || '';
  }
} else {
  // 3. Detección directa PWA o Payload Unificado
  canal = item.canal || 'pwa';
  remitente = item.remitente || item.msisdn || '';
  mensaje = item.mensaje || item.query || 'ofertas';
  lat = item.ubicacion_lat || item.lat || null;
  lon = item.ubicacion_lon || item.lon || null;
}

// Normalización de número venezolano a formato local 0416 / 0426
let limpio = remitente.toString().replace(/[^0-9]/g, '');
if (limpio.startsWith('58') && limpio.length === 12) {
  limpio = '0' + limpio.substring(2);
}

const esMovilnet = limpio.startsWith('0416') || limpio.startsWith('0426');

return [{
  json: {
    canal,
    remitente_original: remitente,
    msisdn_normalizado: limpio,
    es_movilnet: esMovilnet,
    mensaje,
    lat,
    lon,
    timestamp: new Date().toISOString()
  }
}];

// Enriquecimiento de respuesta según canal
const inputData = $input.first().json;
const meta = $('Normalizador Omnicanal').first().json;

return [{
  json: {
    canal: meta.canal,
    destinatario: meta.remitente_original,
    msisdn: inputData.destinatario,
    mensaje_saliente: inputData.mensaje_saliente,
    magic_link: inputData.magic_link,
    zero_rating_activo: inputData.zero_rating_activo,
    ofertas_encontradas: inputData.ofertas_encontradas,
    anillos: inputData.anillos_resumen,
    telegram_webapp_url: inputData.magic_link
  }
}];

